# Let me analyze the test input's 3-components more carefully
# Maybe the rule is about specific component types

test_input_lines = test_input.strip().split('\n')
h, w = len(test_input_lines), len(test_input_lines[0].split())
grid = [[int(c) for c in line.split()] for line in test_input_lines]

def find_components(color):
    visited = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == color and (r, c) not in visited:
                comp = []
                queue = [(r, c)]
                visited.add((r, c))
                while queue:
                    cr, cc = queue.pop(0)
                    comp.append((cr, cc))
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color and (nr, nc) not in visited:
                            visited.add((nr, nc))
                            queue.append((nr, nc))
                components.append(comp)
    return components

def get_component_shape(comp):
    """Get the shape as a frozenset of relative positions"""
    min_r = min(c[0] for c in comp)
    min_c = min(c[1] for c in comp)
    return frozenset((c[0] - min_r, c[1] - min_c) for c in comp)

comps_3 = find_components(3)

# Categorize 3-components by size and shape
shapes_by_size = {}
for i, comp in enumerate(comps_3):
    shape = get_component_shape(comp)
    sz = len(comp)
    if sz not in shapes_by_size:
        shapes_by_size[sz] = []
    shapes_by_size[sz].append((i, shape, comp))

print("3-components by size:")
for sz in sorted(shapes_by_size.keys()):
    shapes = shapes_by_size[sz]
    print(f"\nSize {sz} ({len(shapes)} components):")
    for idx, shape, comp in shapes:
        print(f"  {comp}")
        print(f"    Shape (relative): {sorted(shape)}")
        # Check if it's corner-shaped (has a cell with 2 orthogonal neighbors)
        min_r, min_c = min(c[0] for c in comp), min(c[1] for c in comp)
        shape_set = set((c[0]-min_r, c[1]-min_c) for c in comp)
        for (cr, cc) in comp:
            dr, dc = cr - min_r, cc - min_c
            neighbors = set()
            for offset in [(-1,0), (1,0), (0,-1), (0,1)]:
                if (dr+offset[0], dc+offset[1]) in shape_set:
                    neighbors.add((dr+offset[0], dc+offset[1]))
            if len(neighbors) == 2 and (0,0) in shape_set and (-1,0) in shape_set and (1,0) in shape_set:
                print(f"    ^corner at ({comp[0]}, {comp[1]})")

